import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inp = scanner.nextLine();
        int state = 0;
        String text = inp.replace("at", "@").replace("dot", ".");
        char[] chars = text.toCharArray();
        int length = chars.length;

        if (length > 0) {
            if (chars[0] == '.') {
                chars[0] = 'd'; // placeholder for "dot"
            }
            if (chars[length - 1] == '.') {
                chars[length - 1] = 'd'; // placeholder for "dot"
            }
            if (chars[0] == '@') {
                chars[0] = 'a'; // placeholder for "at"
            }
            if (chars[length - 1] == '@') {
                chars[length - 1] = 'a'; // placeholder for "at"
            }
        }

        for (int i = 0; i < length; i++) {
            if (chars[i] == '@' && state == 0) {
                state = 1;
            } else if (chars[i] == '@') {
                chars[i] = 'a'; // placeholder for "at"
            }
            System.out.print(chars[i]);
        }
        scanner.close();
    }
}
